    {
    }

    void zwp_text_input_manager_v2::bind_func(struct ::wl_client *client, void *data, uint32_t version, uint32_t id)
    {
        zwp_text_input_manager_v2 *that = static_cast<zwp_text_input_manager_v2 *>(data);
        that->add(client, id, version);
    }

    void zwp_text_input_manager_v2::display_destroy_func(struct ::wl_listener *listener, void *data)
    {
        Q_UNUSED(data);
        zwp_text_input_manager_v2 *that = static_cast<zwp_text_input_manager_v2::DisplayDestroyedListener *>(listener)->parent;
        that->m_global = nullptr;
        that->m_globalRemovedEvent = nullptr;
    }

    void zwp_text_input_manager_v2::destroy_func(struct ::wl_resource *client_resource)
    {
        Resource *resource = Resource::fromResource(client_resource);
        Q_ASSERT(resource);
        zwp_text_input_manager_v2 *that = resource->zwp_text_input_manager_v2_object;
        if (Q_LIKELY(that)) {
            that->m_resource_map.remove(resource->client(), resource);
            that->zwp_text_input_manager_v2_destroy_resource(resource);

            that = resource->zwp_text_input_manager_v2_object;
            if (that && that->m_resource == resource)
                that->m_resource = nullptr;
        }
        delete resource;
    }


    void zwp_text_input_manager_v2::globalRemove()
    {
        if (!m_global || m_globalRemovedEvent)
            return;

        struct wl_event_loop *event_loop = wl_display_get_event_loop(m_display);
        m_globalRemovedEvent = wl_event_loop_add_timer(event_loop, deferred_destroy_global_func, this);
        wl_event_source_timer_update(m_globalRemovedEvent, 24 * 60 * 60 * 1000);

        wl_global_remove(m_global);
    }

    zwp_text_input_manager_v2::Resource *zwp_text_input_manager_v2::bind(struct ::wl_client *client, uint32_t id, int version)
    {
        Q_ASSERT_X(!wl_client_get_object(client, id), "QWaylandObject bind", QStringLiteral("binding to object %1 more than once").arg(id).toLocal8Bit().constData());
        struct ::wl_resource *handle = wl_resource_create(client, &::zwp_text_input_manager_v2_interface, version, id);
        return bind(handle);
    }

    zwp_text_input_manager_v2::Resource *zwp_text_input_manager_v2::bind(struct ::wl_resource *handle)
    {
        Resource *resource = zwp_text_input_manager_v2_allocate();
        resource->zwp_text_input_manager_v2_object = this;

        wl_resource_set_implementation(handle, &m_zwp_text_input_manager_v2_interface, resource, destroy_func);
        resource->handle = handle;
        zwp_text_input_manager_v2_bind_resource(resource);
        return resource;
    }
    zwp_text_input_manager_v2::Resource *zwp_text_input_manager_v2::Resource::fromResource(struct ::wl_resource *resource)
    {
        if (Q_UNLIKELY(!resource))
            return nullptr;
        if (wl_resource_instance_of(resource, &::zwp_text_input_manager_v2_interface, &m_zwp_text_input_manager_v2_interface))
            return static_cast<Resource *>(wl_resource_get_user_data(resource));
        return nullptr;
    }

    const struct ::zwp_text_input_manager_v2_interface zwp_text_input_manager_v2::m_zwp_text_input_manager_v2_interface = {
        zwp_text_input_manager_v2::handle_destroy,
        zwp_text_input_manager_v2::handle_get_text_input
    };

