    void zwp_text_input_manager_v2::handle_destroy(
        ::wl_client *client,
        struct wl_resource *resource)
    {
        Q_UNUSED(client);
        Resource *qtResource = Resource::fromResource(resource);
        if (Q_UNLIKELY(!qtResource->zwp_text_input_manager_v2_object)) {
            wl_resource_destroy(resource);
            return;
        }
        static_cast<zwp_text_input_manager_v2 *>(qtResource->zwp_text_input_manager_v2_object)->zwp_text_input_manager_v2_destroy(
            qtResource);
    }

